    public static boolean isLevelItem(Object obj) {
        return obj != null && obj.getClass().getName().endsWith("LevelItem");
    }

    public static boolean isUpgradable(Object levelItem, Object configMgr) {
        try {
            Class<?> cfgClass = Class.forName(CONFIG_MANAGER_CLASS);
            java.lang.reflect.Method m = levelItem.getClass().getDeclaredMethod(
                ITEM_UPGRADABLE_METHOD, cfgClass);
            m.setAccessible(true);
            return (Boolean) m.invoke(levelItem, configMgr);
        } catch (Exception e) { throw new RuntimeException(e); }
    }

