    // ── Listener proxies ──────────────────────────────────────────────────────

    /** Captures the raw forge result object for bonus detection. */
    public static Object createForgeResultListenerProxy(final boolean[] done, final Object[] resultHolder) {
        try {
            Class<?> listenerClass = Class.forName(RESULT_LISTENER_CLASS);
            return java.lang.reflect.Proxy.newProxyInstance(
                Mappings.class.getClassLoader(),
                new Class<?>[]{listenerClass},
                new java.lang.reflect.InvocationHandler() {
                    public Object invoke(Object proxy, java.lang.reflect.Method method, Object[] args) {
                        // requestProcessed(Object result) has a non-String first param
                        if (args != null && args.length > 0
                                && method.getParameterTypes()[0] != String.class) {
                            resultHolder[0] = args[0];
                        }
                        done[0] = true;
                        return null;
                    }
                }
            );
        } catch (Exception e) { throw new RuntimeException(e); }
    }

    /**
     * Wraps an existing ResultListener so individual (non-loop) forge button clicks are also
     * tracked. Forwards every call to {@code original} unchanged, then on success spawns a
     * background thread to record the forge event in ForgeTracker.
     */
    public static Object createChainingForgeListener(final Object original,
                                                      final long oid,
                                                      final int levelBefore,
                                                      final int crystals,
                                                      final int starLevel,
                                                      final Object ctx) {
        try {
            Class<?> listenerClass = Class.forName(RESULT_LISTENER_CLASS);
            return java.lang.reflect.Proxy.newProxyInstance(
                Mappings.class.getClassLoader(),
                new Class<?>[]{listenerClass},
                new java.lang.reflect.InvocationHandler() {
                    public Object invoke(Object proxy, java.lang.reflect.Method method, Object[] args)
                            throws Throwable {
                        method.invoke(original, args);
                        if (args != null && args.length > 0
                                && method.getParameterTypes()[0] != String.class) {
                            final Object result = args[0];
                            new Thread(() -> {
                                try {
                                    Object po = getPlayerObject(ctx);
                                    ForgeTracker.recordForge(
                                        getKnightName(po),
                                        getItemNameByOid(po, oid),
                                        oid, levelBefore + 1, extractLevelAfter(result, levelBefore + 1),
                                        extractForgeDoubleLevel(result), extractForgeHeatBonus(result),
                                        extractForgeBox(result), crystals, getCrystalName(starLevel),
                                        ForgeTracker.dumpResult(result));
                                } catch (Throwable t) {
                                    ForgeTracker.debug("chainingListener bg ERROR: " + t);
                                }
                            }).start();
                        }
                        return null;
                    }
                }
            );
        } catch (Exception e) { throw new RuntimeException(e); }
    }

    public static String getItemNameByOid(Object playerObject, long oid) {
        try {
            for (Object item : getPlayerItems(playerObject)) {
                if (getItemOid(item) == oid) return getItemName(item);
            }
        } catch (Exception e) {}
        return "Unknown";
    }

    public static boolean extractForgeHeatBonus(Object result) {
        return result instanceof String && ((String) result).contains("m.forge_heat_bonus");
    }

    public static boolean extractForgeDoubleLevel(Object result) {
        return result instanceof String && ((String) result).contains("m.forge_skip");
    }

    public static int extractForgeBox(Object result) {
        if (!(result instanceof String)) return 0;
        String s = (String) result;
        int count = 0, idx = 0;
        while ((idx = s.indexOf("m.forge_prize_box", idx)) >= 0) { count++; idx += 17; }
        return count;
    }

    /** Extracts the new level from the result string (~N is 1-indexed display; we return raw 0-indexed). */
    public static int extractLevelAfter(Object result, int levelBefore) {
        if (result instanceof String) {
            String s = (String) result;
            int idx = s.indexOf("m.forge_new_level");
            if (idx >= 0) {
                int tilde = s.indexOf("~", idx);
                if (tilde >= 0) {
                    int end = tilde + 1;
                    while (end < s.length() && Character.isDigit(s.charAt(end))) end++;
                    try { return Integer.parseInt(s.substring(tilde + 1, end)); }
                    catch (NumberFormatException e) {}
                }
            }
        }
        return levelBefore;
    }

    public static Object createResultListenerProxy(final boolean[] flag) {
        return createResultListenerProxy(flag, null);
    }

    public static Object createResultListenerProxy(final boolean[] flag, final String logPrefix) {
        try {
            Class<?> listenerClass = Class.forName(RESULT_LISTENER_CLASS);
            return java.lang.reflect.Proxy.newProxyInstance(
                Mappings.class.getClassLoader(),
                new Class<?>[]{listenerClass},
                new java.lang.reflect.InvocationHandler() {
                    public Object invoke(Object proxy, java.lang.reflect.Method method, Object[] args) {
                        flag[0] = true;
                        if (logPrefix != null) {
                            if (args != null && args.length > 0 && args[0] != null) {
                                SocketInputState.displayChat(logPrefix + " " + args[0], "attention");
                            } else {
                                SocketInputState.displayChat(logPrefix + " done", "feedback");
                            }
                        }
                        return null;
                    }
                }
            );
        } catch (Exception e) { throw new RuntimeException(e); }
    }

    public static Object createConfirmListenerProxy(final boolean[] flag, final String name) {
        try {
            Class<?> listenerClass = Class.forName(CONFIRM_LISTENER_CLASS);
            return java.lang.reflect.Proxy.newProxyInstance(
                Mappings.class.getClassLoader(),
                new Class<?>[]{listenerClass},
                new java.lang.reflect.InvocationHandler() {
                    public Object invoke(Object proxy, java.lang.reflect.Method method, Object[] args) {
                        // Match by parameter structure, not obfuscated name:
                        // success method has 0 params; failure method has 1 String param
                        Class<?>[] params = method.getParameterTypes();
                        if (params.length == 0) {
                        } else if (params.length == 1 && params[0] == String.class) {
                        }
                        flag[0] = true;
                        return null;
                    }
                }
            );
        } catch (Exception e) { throw new RuntimeException(e); }
    }

